SELECT md.chembl_id AS molecule_chembl_id, md.pref_name AS molecule_name, md.max_phase, md.molecule_type, cs.canonical_smiles FROM docs JOIN compound_records ON docs.doc_id = compound_records.doc_id JOIN molecule_dictionary md ON compound_records.molregno = md.molregno JOIN compound_structures cs ON md.molregno = cs.molregno WHERE docs.chembl_id = 'CHEMBL1150404' ORDER BY md.chembl_id ASC
